package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SourceVariableVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property source variable of observed dashboard ")
  void test_source_variable_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> SourceVariableVO.tryFrom(null));
    Assertions.assertEquals(true, SourceVariableVO.from(true).isSourceVariable());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> SourceVariableVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", SourceVariableVO.from(true).toString());
  }
}
